const input = $input.first().json;
const body = input.body ?? input;
const errores = [];

// 1. Validar origen_comunidad
const origen = String(body.origen_comunidad ?? "").trim();
if (!origen) {
  errores.push("El campo 'origen_comunidad' es obligatorio y no puede estar vacío.");
}

// 2. Validar existencia de fechas
const desde = body.ventana_desde;
const hasta = body.ventana_hasta;

if (!desde) {
  errores.push("El campo 'ventana_desde' es obligatorio.");
}
if (!hasta) {
  errores.push("El campo 'ventana_hasta' es obligatorio.");
}

let fechaDesde = null;
let fechaHasta = null;

// 3. Validar formato y lógica de fechas
if (desde) {
  fechaDesde = new Date(desde);
  if (Number.isNaN(fechaDesde.getTime())) {
    errores.push("El formato de 'ventana_desde' no es una fecha válida.");
  }
}

if (hasta) {
  fechaHasta = new Date(hasta);
  if (Number.isNaN(fechaHasta.getTime())) {
    errores.push("El formato de 'ventana_hasta' no es una fecha válida.");
  }
}

if (fechaDesde && fechaHasta && !Number.isNaN(fechaDesde.getTime()) && !Number.isNaN(fechaHasta.getTime())) {
  if (fechaDesde >= fechaHasta) {
    errores.push("El período de fechas no es válido: 'ventana_desde' debe ser estrictamente menor que 'ventana_hasta'.");
  }
}

// 4. Procesar opciones con valores por defecto
const opciones = body.opciones ?? {};
const opcionesNormalizadas = {
  idioma: opciones.idioma ?? "es",
  tono: opciones.tono ?? "inspirador",
  min_actividades_utiles: Math.max(1, Number(opciones.min_actividades_utiles ?? 3)),
  max_actividades: Math.min(100, Math.max(1, Number(opciones.max_actividades ?? 30)))
};

const esValido = errores.length === 0;

// 5. Retornar resultado estructurado para el flujo de n8n
return [{
  json: {
    es_valido: esValido,
    errores: errores,
    datos_validados: esValido ? {
      origen_comunidad: origen,
      ventana_desde: fechaDesde.toISOString(),
      ventana_hasta: fechaHasta.toISOString(),
      opciones: opcionesNormalizadas,
      // Clave canónica: mismos datos efectivos => misma solicitud.
      // Se usa la fuente tal como se valida contra fuente.nombre en PostgreSQL.
      clave_idempotencia: 'newsletter:v1:' + JSON.stringify({
        origen_comunidad: origen,
        ventana_desde: fechaDesde.toISOString(),
        ventana_hasta: fechaHasta.toISOString(),
        opciones: opcionesNormalizadas
      })
    } : null
  }
}];

