const row = $input.first().json;
const request = $('W2 — Validar solicitud').first().json.datos_validados;

const actividades = Array.isArray(row.actividades)
  ? row.actividades
  : typeof row.actividades === "string"
    ? JSON.parse(row.actividades)
    : [];

const utiles = actividades.filter((a) => {
  const texto = String(
    a.analisis?.evidencia_clave ||
    a.analisis?.resumen ||
    a.texto_original ||
    ""
  ).trim();

  return texto.length >= 30;
});

const minimo =
  request.opciones.min_actividades_utiles;

if (utiles.length < minimo) {
  return [{
    json: {
      status: "sin_contenido_suficiente",
      newsletter_generado: false,
      activo_persistido: false,
      mensaje: "No hay suficiente contenido útil para generar el newsletter.",
      meta: {
        origen_comunidad: request.origen_comunidad,
        ventana_desde: request.ventana_desde,
        ventana_hasta: request.ventana_hasta,
        actividades_recuperadas: actividades.length,
        actividades_utiles: utiles.length,
        minimo_requerido: minimo
      }
    }
  }];
}

return [{
  json: {
    status: "listo_para_generar",
    origen_comunidad: request.origen_comunidad,
    ventana_desde: request.ventana_desde,
    ventana_hasta: request.ventana_hasta,
    opciones: request.opciones,
    actividades_utiles: utiles
  }
}];

