const contexto = $('W4 — Evaluar suficiencia y preparar evidencias').first().json;
const newsletter = $('W6 — Normalizar newsletter').first().json;

if (newsletter.status !== 'generado') {
  throw new Error('La newsletter no está lista para persistir.');
}

const actividades = contexto.actividades_utiles ?? [];

if (!Array.isArray(actividades) || actividades.length === 0) {
  throw new Error('No hay actividades originales para validar.');
}

// Construimos el conjunto de IDs disponibles en la entrada.
const idsDisponibles = new Set(
  actividades.map(a => Number(a.id_actividad))
);

const idsUsados = (newsletter.secciones ?? [])
  .flatMap(seccion => seccion.ids_actividades ?? [])
  .map(Number);

const idsInvalidos = [...new Set(idsUsados)]
  .filter(id => !Number.isInteger(id) || !idsDisponibles.has(id));

if (idsInvalidos.length > 0) {
  throw new Error(
    `La newsletter contiene IDs de actividades que no pertenecen a la entrada: ${idsInvalidos.join(', ')}`
  );
}

// Detectamos posibles diferencias entre la fuente solicitada
// y la fuente declarada en las actividades.
const fuentesDetectadas = [
  ...new Set(
    actividades
      .map(a => a.origen_comunidad)
      .filter(Boolean)
  )
];


return [{
  json: {
    origen_comunidad: contexto.origen_comunidad,
    ventana_desde: contexto.ventana_desde,
    ventana_hasta: contexto.ventana_hasta,
    opciones: contexto.opciones,
    total_actividades_utiles: actividades.length,
    ids_actividades_referenciadas: [...new Set(idsUsados)],
    newsletter: {
      status: newsletter.status,
      titulo: newsletter.titulo,
      introduccion: newsletter.introduccion,
      secciones: newsletter.secciones,
      cierre: newsletter.cierre,
      contenido_completo: newsletter.contenido_completo
    },
    actividades_utiles: actividades
  }
}];

const input = $input.first().json;

// El resultado puede llegar como JSON serializado en "text"
// o como un objeto JSON directamente.
let newsletter = input.text ?? input.output ?? input;

if (typeof newsletter === "string") {
  newsletter = newsletter
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  try {
    newsletter = JSON.parse(newsletter);
  } catch (error) {
    throw new Error(
      `El generador no devolvió un JSON válido: ${error.message}`
    );
  }
}

if (
  !newsletter ||
  typeof newsletter !== "object" ||
  Array.isArray(newsletter)
) {
  throw new Error("La salida del generador debe ser un objeto JSON.");
}

if (newsletter.status !== "generado") {
  throw new Error(
    `La newsletter no está lista para persistir. Estado: ${
      newsletter.status ?? "no especificado"
    }`
  );
}

if (
  typeof newsletter.titulo !== "string" ||
  !newsletter.titulo.trim()
) {
  throw new Error("La newsletter no contiene un título válido.");
}

if (!Array.isArray(newsletter.secciones)) {
  throw new Error("La newsletter debe contener un array de secciones.");
}

for (const [index, seccion] of newsletter.secciones.entries()) {
  if (
    typeof seccion.titulo !== "string" ||
    !seccion.titulo.trim() ||
    typeof seccion.contenido !== "string" ||
    !seccion.contenido.trim()
  ) {
    throw new Error(
      `La sección ${index + 1} no tiene título o contenido válido.`
    );
  }

  if (
    seccion.ids_actividades !== undefined &&
    (
      !Array.isArray(seccion.ids_actividades) ||
      !seccion.ids_actividades.every(
        id => Number.isInteger(Number(id)) && Number(id) > 0
      )
    )
  ) {
    throw new Error(
      `Las referencias de actividades de la sección ${index + 1} no son válidas.`
    );
  }
}

return [{
  json: {
    status: newsletter.status,
    titulo: newsletter.titulo.trim(),
    introduccion: newsletter.introduccion ?? "",
    secciones: newsletter.secciones,
    cierre: newsletter.cierre ?? "",
    contenido_completo: [
      newsletter.titulo,
      newsletter.introduccion,
      ...newsletter.secciones.map(
        s => `${s.titulo}\n${s.contenido}`
      ),
      newsletter.cierre
    ].filter(Boolean).join("\n\n"),
    newsletter
  }
}];

